steps.summary:
**Bash** python3 ../plugin/dev-team/scripts/dt.py status --skill api-probe | grep -E "mode|probes_|evidence"; python3 ../plugin/dev-team/scripts/dt.py probes --scan; for p in PB-01-sharadar-coverage PB-02-yahoo-coverage; do echo "== $p"; python3 -c "
import json,sys;r=json.load(open('probes/$p/evidence/results.json'));print(r['script_hash'],r['run_at'],r['runner'],r['base_url'],r.get('error'))
for k,v in r['checks'].items(): print(k,v['pass'],json.dumps(v['observed']),v.get('note',''))"; done

